/// `example.org/ui-tui@0.3.0/Deep`.
pub trait Deep {
    fn make(&mut self, arg0: u32, arg1: u32) -> hd_run_wasmtime::native::HostResult<DeepMakeResult>;
    fn take(&mut self, arg0: DeepTakeArg0) -> hd_run_wasmtime::native::HostResult<u32>;
}

/// Calls the method at index `method` of the registered `Deep` with its
/// encoded arguments and returns its encoded result, or a suspending
/// method's pending call.
#[allow(non_snake_case)]
pub fn dispatch_Deep(provider: &mut dyn std::any::Any, method: usize, args: &[u8], handles: &mut hd_run_wasmtime::native::Handles) -> hd_run_wasmtime::native::Dispatched {
    let provider = hd_run_wasmtime::native::wire::provider::<Box<dyn Deep>>(provider)?;
    match method {
        0 => {
            let d = &mut hd_run_wasmtime::native::wire::Decoder::new(args);
            let arg0 = d.unsigned::<u32>()?;
            let arg1 = d.unsigned::<u32>()?;
            d.finish()?;
            let value = provider.make(arg0, arg1).map_err(hd_run_wasmtime::native::Failure::Threw)?;
            let mut enc = hd_run_wasmtime::native::wire::Encoder::new(handles);
            let e = &mut enc;
            DeepMakeResult::wire_encode(value, e)?;
            Ok(hd_run_wasmtime::native::Answer::Ready(enc.into_bytes()))
        }
        1 => {
            let d = &mut hd_run_wasmtime::native::wire::Decoder::new(args);
            let arg0 = DeepTakeArg0::wire_decode(d)?;
            d.finish()?;
            let value = provider.take(arg0).map_err(hd_run_wasmtime::native::Failure::Threw)?;
            let mut enc = hd_run_wasmtime::native::wire::Encoder::new(handles);
            let e = &mut enc;
            e.unsigned(u64::from(value));
            Ok(hd_run_wasmtime::native::Answer::Ready(enc.into_bytes()))
        }
        _ => Err(hd_run_wasmtime::native::wire::unknown_method(method).into()),
    }
}

/// The providers of this module's root host traits.
pub struct Bindings;

impl Bindings {
    #[must_use]
    pub fn builder() -> BindingsBuilder {
        BindingsBuilder {
            deep: None,
        }
    }
}

pub struct BindingsBuilder {
    deep: Option<Box<dyn Deep>>,
}

impl BindingsBuilder {
    #[must_use]
    pub fn deep(mut self, provider: impl Deep + 'static) -> Self {
        self.deep = Some(Box::new(provider));
        self
    }

    /// The registry, or the first root trait left without a provider.
    pub fn build(self) -> Result<hd_run_wasmtime::native::Bindings, hd_run_wasmtime::native::Unregistered> {
        let mut bindings = hd_run_wasmtime::native::Bindings::new(CONTRACT);
        let Some(provider) = self.deep else {
            return Err(hd_run_wasmtime::native::Unregistered::new("example.org/ui-tui@0.3.0/Deep"));
        };
        bindings.register_dispatch("example.org/ui-tui@0.3.0/Deep", "hd:pkg:deep", Box::new(provider), dispatch_Deep);
        Ok(bindings)
    }
}
